interface.definition:
a!localVariables(
  local!isCollapsed: false,
  {
    #"SYSTEM_SYSRULES_sideBySideLayout"(
      alignVertical: "MIDDLE",
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            label: "Title",
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: if(
                  local!isCollapsed,
                  "angle-right",
                  "angle-down"
                ),
                link: #"SYSTEM_SYSRULES_dynamicLink"(
                  value: not(local!isCollapsed),
                  saveInto: local!isCollapsed
                ),
                linkStyle: "STANDALONE",
                /*showWhen: a!defaultValue(ri!isCollapsible, false),*/
                showWhen: false,
                color: "ACCENT",
                size: "MEDIUM_PLUS"
              ),
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!title,
                color: "ACCENT",
                size: "MEDIUM_PLUS",
                style: "STRONG"
              )
            }
          )
        )
      },
      showWhen: not(isnull(ri!title))
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: ri!contents,
      height: "AUTO",
      showWhen: and(
        ri!showWhen,
        local!isCollapsed = false
      ),
      style: "NONE",
      /* Parameter for later versions */
      /*shape: "ROUNDED",*/
      padding: "STANDARD",
      marginBelow: "STANDARD",
      showBorder: false,
      showShadow: true
    )
  }
)
